// Synthesised soundtrack, rendered offline so it is identical in the browser
// and in the exported MP4. Every cue is read from the same timeline and graph as the picture.
import { mulberry32 } from './util.js';
import { DURATION, BEAT, STAGES, T } from './timeline.js';
import { buildGraph } from './graph.js';

const NOTE = {
  F1: 43.65, G1: 49.0, A1: 55.0, Bb1: 58.27, C2: 65.41, D2: 73.42, F2: 87.31,
  Bb2: 116.54, C3: 130.81, D3: 146.83, E3: 164.81, F3: 174.61, G3: 196.0, A3: 220.0, Bb3: 233.08,
  C4: 261.63, D4: 293.66, E4: 329.63, F4: 349.23, G4: 392.0, A4: 440.0,
  C5: 523.25, D5: 587.33, E5: 659.25, F5: 698.46, G5: 783.99, A5: 880.0,
  C6: 1046.5, D6: 1174.66, E6: 1318.51, F6: 1396.91, G6: 1567.98, A6: 1760.0,
};

// Two-bar harmony in F: Fmaj9 · Dm9 · B♭maj7 · C6/9, twice, then home.
const BARS = [
  { t: 0, root: NOTE.F1, chord: [NOTE.F3, NOTE.A3, NOTE.C4, NOTE.E4, NOTE.G4] },
  { t: 2, root: NOTE.D2, chord: [NOTE.D3, NOTE.F3, NOTE.A3, NOTE.C4, NOTE.E4] },
  { t: 4, root: NOTE.Bb1, chord: [NOTE.Bb2, NOTE.D3, NOTE.F3, NOTE.A3, NOTE.C4] },
  { t: 6, root: NOTE.C2, chord: [NOTE.C3, NOTE.E3, NOTE.G3, NOTE.A3, NOTE.D4] },
  { t: 8, root: NOTE.F1, chord: [NOTE.F3, NOTE.A3, NOTE.C4, NOTE.E4, NOTE.G4] },
  { t: 10, root: NOTE.D2, chord: [NOTE.D3, NOTE.F3, NOTE.A3, NOTE.C4, NOTE.E4] },
  { t: 12, root: NOTE.Bb1, chord: [NOTE.Bb2, NOTE.D3, NOTE.F3, NOTE.A3, NOTE.C4] },
  { t: 14, root: NOTE.C2, chord: [NOTE.C3, NOTE.E3, NOTE.G3, NOTE.A3, NOTE.D4] },
  { t: 16, root: NOTE.F1, chord: [NOTE.F3, NOTE.A3, NOTE.C4, NOTE.E4, NOTE.G4] },
];
const PENT = [NOTE.F4, NOTE.G4, NOTE.A4, NOTE.C5, NOTE.D5, NOTE.F5, NOTE.G5, NOTE.A5, NOTE.C6, NOTE.D6];
const GROOVE = { half: STAGES[2].at, full: STAGES[4].at, drop: T.split, end: T.identityOut };

export const renderSoundtrack = async ({ sampleRate = 48000 } = {}) => {
  const length = Math.ceil(DURATION * sampleRate);
  const ctx = new OfflineAudioContext(2, length, sampleRate);
  const rand = mulberry32(2026);

  // Shared white noise (seeded, so the render is reproducible).
  const noiseBuf = ctx.createBuffer(2, sampleRate * 2, sampleRate);
  for (let c = 0; c < 2; c++) {
    const d = noiseBuf.getChannelData(c);
    for (let i = 0; i < d.length; i++) d[i] = rand() * 2 - 1;
  }

  // Master chain: bus → glue compressor → limiter → out.
  const master = ctx.createGain();
  master.gain.value = 0.85;
  const glue = ctx.createDynamicsCompressor();
  glue.threshold.value = -16;
  glue.knee.value = 8;
  glue.ratio.value = 3;
  glue.attack.value = 0.004;
  glue.release.value = 0.2;
  const limiter = ctx.createDynamicsCompressor();
  limiter.threshold.value = -2;
  limiter.knee.value = 0;
  limiter.ratio.value = 20;
  limiter.attack.value = 0.001;
  limiter.release.value = 0.08;
  master.connect(glue).connect(limiter).connect(ctx.destination);

  // Reverb: a long, soft synthetic hall.
  const irLen = Math.floor(sampleRate * 3.2);
  const ir = ctx.createBuffer(2, irLen, sampleRate);
  for (let c = 0; c < 2; c++) {
    const d = ir.getChannelData(c);
    for (let i = 0; i < irLen; i++) d[i] = (rand() * 2 - 1) * Math.pow(1 - i / irLen, 3.4);
  }
  const reverb = ctx.createConvolver();
  reverb.buffer = ir;
  const reverbReturn = ctx.createGain();
  reverbReturn.gain.value = 0.34;
  reverb.connect(reverbReturn).connect(master);

  // Music bus ducks under the kick (sidechain feel).
  const music = ctx.createGain();
  music.connect(master);
  const drums = ctx.createGain();
  drums.connect(master);

  const send = (node, amount) => {
    const g = ctx.createGain();
    g.gain.value = amount;
    node.connect(g).connect(reverb);
  };
  const env = (param, t, peak, attack, decay, floor = 0.0001) => {
    param.setValueAtTime(floor, t);
    param.exponentialRampToValueAtTime(peak, t + attack);
    param.exponentialRampToValueAtTime(floor, t + attack + decay);
  };

  const noise = (t, dur, { type = 'bandpass', freq = 2000, q = 0.8, gain = 0.2, attack = 0.002, decay, pan = 0, out = master, reverbAmt = 0 } = {}) => {
    const src = ctx.createBufferSource();
    src.buffer = noiseBuf;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = type;
    f.frequency.value = freq;
    f.Q.value = q;
    const g = ctx.createGain();
    env(g.gain, t, gain, attack, decay ?? dur);
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    src.connect(f).connect(g).connect(p).connect(out);
    if (reverbAmt) send(p, reverbAmt);
    src.start(t, rand() * 1.5);
    src.stop(t + attack + (decay ?? dur) + 0.05);
    return { f, g };
  };

  const tone = (t, freq, { type = 'sine', gain = 0.2, attack = 0.005, decay = 0.4, pan = 0, out = music, reverbAmt = 0, cutoff, detune = 0 } = {}) => {
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.value = freq;
    o.detune.value = detune;
    const g = ctx.createGain();
    env(g.gain, t, gain, attack, decay);
    let node = o;
    if (cutoff) {
      const f = ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.setValueAtTime(cutoff, t);
      f.frequency.exponentialRampToValueAtTime(Math.max(120, cutoff * 0.25), t + attack + decay);
      node.connect(f);
      node = f;
    }
    const p = ctx.createStereoPanner();
    p.pan.value = pan;
    node.connect(g).connect(p).connect(out);
    if (reverbAmt) send(p, reverbAmt);
    o.start(t);
    o.stop(t + attack + decay + 0.05);
  };

  const kick = (t, { gain = 0.6, f0 = 120, f1 = 42, decay = 0.4 } = {}) => {
    const o = ctx.createOscillator();
    o.frequency.setValueAtTime(f0, t);
    o.frequency.exponentialRampToValueAtTime(f1, t + 0.1);
    const g = ctx.createGain();
    env(g.gain, t, gain, 0.004, decay);
    o.connect(g).connect(drums);
    o.start(t);
    o.stop(t + decay + 0.05);
    music.gain.setValueAtTime(1, t);
    music.gain.linearRampToValueAtTime(0.6, t + 0.012);
    music.gain.setTargetAtTime(1, t + 0.02, 0.08);
  };
  const shaker = (t, gain = 0.05, pan = 0.2) => noise(t, 0.05, { type: 'highpass', freq: 8200, q: 0.6, gain, attack: 0.012, decay: 0.05, pan, out: drums });
  const snap = (t, gain = 0.2) => {
    noise(t, 0.06, { type: 'bandpass', freq: 2300, q: 1.6, gain, decay: 0.07, out: drums, reverbAmt: 0.5 });
    tone(t, 1800, { gain: gain * 0.25, attack: 0.001, decay: 0.03, out: drums });
  };
  // A soft two-partial chime, like a desktop notification.
  const chime = (t, freq, gain = 0.07, pan = 0) => {
    tone(t, freq, { gain, attack: 0.003, decay: 0.55, pan, out: master, reverbAmt: 0.55 });
    tone(t, freq * 2.001, { gain: gain * 0.35, attack: 0.003, decay: 0.25, pan, out: master, reverbAmt: 0.55 });
  };
  const bell = (t, freq, gain = 0.28) => {
    tone(t, freq, { gain, attack: 0.002, decay: 2.2, out: master, reverbAmt: 0.9 });
    tone(t, freq * 2.76, { gain: gain * 0.16, attack: 0.002, decay: 0.8, out: master, reverbAmt: 0.9 });
    tone(t, freq * 5.4, { gain: gain * 0.05, attack: 0.002, decay: 0.35, out: master, reverbAmt: 0.9 });
  };
  const pluck = (t, freq, gain = 0.16, pan = 0) => {
    tone(t, freq, { type: 'triangle', gain, attack: 0.003, decay: 0.34, pan, reverbAmt: 0.4 });
    tone(t, freq * 2, { type: 'sine', gain: gain * 0.2, attack: 0.003, decay: 0.14, pan, reverbAmt: 0.4 });
  };
  const whoosh = (t, dur, { from = 400, to = 4000, gain = 0.18, panFrom = -0.6, panTo = 0.6 } = {}) => {
    const src = ctx.createBufferSource();
    src.buffer = noiseBuf;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 1.2;
    f.frequency.setValueAtTime(from, t);
    f.frequency.exponentialRampToValueAtTime(to, t + dur * 0.6);
    f.frequency.exponentialRampToValueAtTime(from * 1.5, t + dur);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(gain, t + dur * 0.6);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    const p = ctx.createStereoPanner();
    p.pan.setValueAtTime(panFrom, t);
    p.pan.linearRampToValueAtTime(panTo, t + dur);
    src.connect(f).connect(g).connect(p).connect(master);
    send(p, 0.35);
    src.start(t, rand());
    src.stop(t + dur + 0.05);
  };
  const boom = (t, gain = 0.8, dur = 1.6) => {
    const o = ctx.createOscillator();
    o.frequency.setValueAtTime(64, t);
    o.frequency.exponentialRampToValueAtTime(30, t + dur);
    const g = ctx.createGain();
    env(g.gain, t, gain, 0.008, dur);
    o.connect(g).connect(master);
    o.start(t);
    o.stop(t + dur + 0.05);
    noise(t, 1.2, { type: 'lowpass', freq: 700, q: 0.5, gain: gain * 0.25, decay: 1.2, reverbAmt: 0.6 });
  };
  const shimmer = (t, notes, gain = 0.05) => notes.forEach((f, i) => tone(t + i * 0.03, f, { gain, attack: 0.01, decay: 1.8, pan: (i % 2 ? 1 : -1) * 0.4, out: master, reverbAmt: 0.9 }));
  const pad = (t, freqs, dur, gain = 0.05) => {
    freqs.forEach((freq, n) => {
      [-7, 0, 6].forEach((cents) => {
        const o = ctx.createOscillator();
        o.type = cents ? 'sawtooth' : 'triangle';
        o.frequency.value = freq;
        o.detune.value = cents;
        const f = ctx.createBiquadFilter();
        f.type = 'lowpass';
        f.frequency.value = 900 + n * 140;
        f.Q.value = 0.3;
        const g = ctx.createGain();
        g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(gain, t + 0.45);
        g.gain.setValueAtTime(gain, t + dur - 0.2);
        g.gain.linearRampToValueAtTime(0, t + dur + 0.7);
        const p = ctx.createStereoPanner();
        p.pan.value = (cents / 7) * 0.5;
        o.connect(f).connect(g).connect(p).connect(music);
        send(p, 0.55);
        o.start(t);
        o.stop(t + dur + 0.8);
      });
    });
  };
  const bass = (t, freq, dur, gain = 0.3) => {
    tone(t, freq, { type: 'sawtooth', gain: gain * 0.7, attack: 0.006, decay: dur, cutoff: 560 });
    tone(t, freq, { type: 'sine', gain, attack: 0.006, decay: dur });
  };

  const at = (t) => Math.max(0, t);
  const G = buildGraph('landscape');
  const panOf = (x) => Math.max(-0.75, Math.min(0.75, x / 1500));

  // ── Harmony: soft pads throughout, a bass line once the groove starts ─────
  BARS.forEach((bar, i) => {
    const end = BARS[i + 1]?.t ?? T.fadeOut;
    const g = bar.t >= T.endcard - 0.4 ? 0.05 : bar.t < GROOVE.half ? 0.03 : 0.04;
    pad(bar.t, bar.chord, end - bar.t, g);
    if (bar.t >= GROOVE.end) return;
    for (let t = Math.max(bar.t, GROOVE.half); t < end - 0.01; t += BEAT) {
      if (t < GROOVE.full && Math.round((t - GROOVE.half) / BEAT) % 2) continue;
      bass(t, bar.root * (t >= GROOVE.drop && Math.round(t / BEAT) % 4 === 3 ? 2 : 1), t < GROOVE.full ? 0.4 : 0.22, t < GROOVE.full ? 0.22 : 0.28);
    }
  });

  // ── Rhythm: builds with the system ────────────────────────────────────────
  for (let t = GROOVE.half; t < GROOVE.end - 0.01; t += BEAT) {
    const full = t >= GROOVE.full;
    const beat = Math.round((t - GROOVE.half) / BEAT);
    if (full || beat % 2 === 0) kick(t, { gain: full ? 0.5 : 0.36, f0: 115, f1: 42, decay: 0.32 });
    shaker(t + BEAT / 2, full ? 0.045 : 0.03, 0.25);
    if (full && beat % 2 === 1) snap(t, t >= GROOVE.drop ? 0.17 : 0.13);
  }
  for (let t = GROOVE.full; t < GROOVE.end - 0.01; t += BEAT / 4) {
    const k = Math.round((t - GROOVE.full) / (BEAT / 4));
    if (k % 2) shaker(t, t >= GROOVE.drop ? 0.028 : 0.018, -0.3);
  }

  // ── Stage cues: a breath before each stage, a soft landing on it ──────────
  STAGES.forEach((s, i) => {
    if (i > 0 && s.at < GROOVE.drop) whoosh(at(s.at - 0.45), 0.6, { from: 500, to: 3800, gain: 0.07, panFrom: -0.5, panTo: 0.5 });
    if (s.at < GROOVE.half) kick(s.at, { gain: 0.26, f0: 90, f1: 40, decay: 0.4 });
  });

  // Every component that lands gets a note; the melody climbs as the system grows.
  const landed = G.nodes.filter((n) => !n.origin).sort((a, b) => a.at - b.at);
  landed.forEach((n, i) => {
    const note = PENT[Math.min(PENT.length - 1, Math.floor((i / landed.length) * PENT.length * 0.85) + (i % 2))];
    pluck(n.at, note, 0.085, panOf(n.base[0]));
    if (n.stackAt) tone(n.stackAt + 0.05, note * 2, { gain: 0.018, attack: 0.002, decay: 0.12, pan: panOf(n.base[0]), reverbAmt: 0.5, out: master });
  });
  // Links drawing in: tiny ticks, like relays closing.
  G.edges.filter((e) => !e.cloned && e.at < GROOVE.drop).forEach((e) => noise(e.at + 0.48, 0.004, { type: 'highpass', freq: 6000, gain: 0.012, decay: 0.005, pan: (e.i % 5) / 5 - 0.4 }));
  // Observability lights every workload: a quick run of bells.
  for (let k = 0; k < 8; k++) chime(10.0 + k * 0.06, PENT[2 + k] || NOTE.A5, 0.035, k % 2 ? 0.35 : -0.35);

  // ── The split: riser, drop, and the system triples ────────────────────────
  {
    const src = ctx.createBufferSource();
    src.buffer = noiseBuf;
    src.loop = true;
    const f = ctx.createBiquadFilter();
    f.type = 'bandpass';
    f.Q.value = 0.9;
    f.frequency.setValueAtTime(400, GROOVE.drop - 1.3);
    f.frequency.exponentialRampToValueAtTime(7000, GROOVE.drop - 0.02);
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, GROOVE.drop - 1.3);
    g.gain.exponentialRampToValueAtTime(0.16, GROOVE.drop - 0.02);
    g.gain.linearRampToValueAtTime(0, GROOVE.drop);
    src.connect(f).connect(g).connect(master);
    src.start(GROOVE.drop - 1.3);
    src.stop(GROOVE.drop + 0.02);
  }
  boom(GROOVE.drop, 0.55, 1.8);
  shimmer(GROOVE.drop, [NOTE.F5, NOTE.A5, NOTE.C6, NOTE.E6], 0.035);
  whoosh(GROOVE.drop + 0.05, 1.0, { from: 300, to: 2600, gain: 0.1, panFrom: 0.6, panTo: -0.6 });

  // Rolling deploy: an arpeggio that climbs with the wave.
  const [r0, r1] = T.rollout;
  const steps = Math.round((r1 - r0) / (BEAT / 4));
  for (let k = 0; k <= steps; k++) {
    const t = r0 + k * (BEAT / 4);
    pluck(t, PENT[k % PENT.length] * (k >= PENT.length ? 2 : 1), 0.05, -0.7 + (1.4 * k) / steps);
  }
  shimmer(r1, [NOTE.C6, NOTE.E6, NOTE.G6, NOTE.A6], 0.025);

  // ── End card: the groove lets go, a bell, and home ────────────────────────
  whoosh(T.endcard - 0.45, 0.7, { from: 800, to: 6000, gain: 0.09, panFrom: -0.6, panTo: 0.6 });
  bell(T.endcard + 0.1, NOTE.A5, 0.2);
  bell(T.endcard + 0.11, NOTE.E6, 0.09);
  boom(T.endcard + 0.1, 0.25, 1.8);

  const rendered = await ctx.startRendering();

  // Normalise to −1 dBFS and fade the tail so the loop point is silent.
  let peak = 0;
  for (let c = 0; c < rendered.numberOfChannels; c++) {
    const d = rendered.getChannelData(c);
    for (let i = 0; i < d.length; i++) peak = Math.max(peak, Math.abs(d[i]));
  }
  const gain = peak > 0 ? 0.89 / peak : 1;
  const fadeStart = Math.floor(T.fadeOut * sampleRate);
  for (let c = 0; c < rendered.numberOfChannels; c++) {
    const d = rendered.getChannelData(c);
    for (let i = 0; i < d.length; i++) {
      const tail = i > fadeStart ? 1 - (i - fadeStart) / (d.length - fadeStart) : 1;
      d[i] *= gain * tail * tail;
    }
  }
  return rendered;
};

export const encodeWav = (buffer) => {
  const channels = buffer.numberOfChannels;
  const frames = buffer.length;
  const bytes = new DataView(new ArrayBuffer(44 + frames * channels * 2));
  const str = (o, s) => [...s].forEach((ch, i) => bytes.setUint8(o + i, ch.charCodeAt(0)));
  str(0, 'RIFF');
  bytes.setUint32(4, 36 + frames * channels * 2, true);
  str(8, 'WAVE');
  str(12, 'fmt ');
  bytes.setUint32(16, 16, true);
  bytes.setUint16(20, 1, true);
  bytes.setUint16(22, channels, true);
  bytes.setUint32(24, buffer.sampleRate, true);
  bytes.setUint32(28, buffer.sampleRate * channels * 2, true);
  bytes.setUint16(32, channels * 2, true);
  bytes.setUint16(34, 16, true);
  str(36, 'data');
  bytes.setUint32(40, frames * channels * 2, true);
  const data = [...Array(channels)].map((_, c) => buffer.getChannelData(c));
  let o = 44;
  for (let i = 0; i < frames; i++) {
    for (let c = 0; c < channels; c++) {
      const v = Math.max(-1, Math.min(1, data[c][i]));
      bytes.setInt16(o, v < 0 ? v * 0x8000 : v * 0x7fff, true);
      o += 2;
    }
  }
  return bytes.buffer;
};
